CREATE VIEW "EXT"."CSA_RPP_DETALLE_SVW" ( "TIPO_INFORME", "PERIODSEQ", "POSITIONSEQ", "PERIODO", "PERIODO_FORMATO", "COD_AGENTE", "NOMBRE_AGENTE", "NIF", "TIPO_AGE", "COD_PROD", "CODIGO_POLIZA", "NOMBRE_PRODUCTO", "TIPO_RECIBO", "FECHA_EMISION", "FECHA_COBRO", "POLIZAS_FIS", "POLIZAS_CORR", "PRIMAS", "SOLO_DIFERENCIAS", "FEC_ACTUALIZACION" ) AS (SELECT "TIPO_INFORME" , "PERIODSEQ" , "POSITIONSEQ" , "PERIODO" , "PERIODO_FORMATO" , "COD_AGENTE" , "NOMBRE_AGENTE" , "NIF" , "TIPO_AGE" , "COD_PROD" , "CODIGO_POLIZA" , "NOMBRE_PRODUCTO" , "TIPO_RECIBO" , "FECHA_EMISION" , "FECHA_COBRO" , "POLIZAS_FIS" , "POLIZAS_CORR" , "PRIMAS" , "SOLO_DIFERENCIAS" , "FEC_ACTUALIZACION" FROM EXT.OUT_RPP_DETALLE_FINAL_REP
	WHERE TIPO_INFORME = 'CIERRE'
	AND PERIODSEQ IN (SELECT PERIODSEQ FROM EXT.LIB_CREAR_TABLAS:N_MESES(13))) WITH  STRUCTURED PRIVILEGE CHECK